arguments.file_text:
@using sv_fa463c93198b4e7c938f438ce6449c95.Services

<div class="profile-section">
    <h3>Profile</h3>

    @if (Profile is null)
    {
        <p class="text-muted">Loading profile…</p>
        return;
    }

    <div class="avatar-area">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(_avatarUrl))
            {
                <img src="@_avatarUrl" alt="Avatar" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
        </div>
        <div class="avatar-url">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" value="@_avatarUrl" disabled />
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Display Name</label>
        <input type="text" class="form-control" @bind="_displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" @bind="_email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Bio</label>
        <textarea class="form-control" rows="4" @bind="_bio"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
            Discard Changes
        </button>
    </div>

    @if (_showSuccess)
    {
        <div class="alert alert-success mt-3 toast-message" role="alert">
            ✅ Profile saved successfully!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_saving)
        {
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);

        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        _showSuccess = false;
    }
}

.profile-section {
    max-width: 600px;
}

.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
}

.avatar-preview {
    flex-shrink: 0;
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #dee2e6;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e9ecef;
    font-size: 2rem;
}

.avatar-url {
    flex: 1;
    min-width: 0;
}

.button-group {
    display: flex;
    gap: 0.75rem;
}

.toast-message {
    animation: fadeInUp 0.3s ease;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@using sv_fa463c93198b4e7c938f438ce6449c95.Services

<div class="notifications-section">
    <h3>Notifications</h3>

    @if (Prefs is null)
    {
        <p class="text-muted">Loading notification preferences…</p>
        return;
    }

    <div class="toggle-group">
        <div class="toggle-row">
            <div class="toggle-info">
                <span class="toggle-label">Email Notifications</span>
                <span class="toggle-desc">Receive notifications via email</span>
            </div>
            <label class="switch">
                <input type="checkbox" checked="@_emailNotifications"
                       @onchange="e => _emailNotifications = (bool)e.Value!" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <div class="toggle-info">
                <span class="toggle-label">Push Notifications</span>
                <span class="toggle-desc">Receive push notifications in browser</span>
            </div>
            <label class="switch">
                <input type="checkbox" checked="@_pushNotifications"
                       @onchange="e => _pushNotifications = (bool)e.Value!" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <div class="toggle-info">
                <span class="toggle-label">Weekly Digest</span>
                <span class="toggle-desc">Get a weekly summary of activity</span>
            </div>
            <label class="switch">
                <input type="checkbox" checked="@_weeklyDigest"
                       @onchange="e => _weeklyDigest = (bool)e.Value!" />
                <span class="slider"></span>
            </label>
        </div>
    </div>

    <h5 class="mt-4">Muted Channels</h5>
    <div class="channel-list">
        @foreach (var channel in _allChannels)
        {
            var isMuted = _mutedChannels.Contains(channel);
            <label class="channel-item">
                <input type="checkbox" checked="@isMuted"
                       @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                <span>@channel</span>
                @if (isMuted)
                {
                    <span class="badge bg-secondary">Muted</span>
                }
            </label>
        }
    </div>

    <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
        @(_saving ? "Saving…" : "Save Preferences")
    </button>

    @if (_showSuccess)
    {
        <div class="alert alert-success mt-3" role="alert">
            ✅ Notification preferences saved!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _allChannels =
        ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_saving)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);

        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

