arguments.file_text:
@* Confirmation dialog shown before revoking a session *@

@if (Visible)
{
    <div class="dialog-backdrop" @onclick="Cancel">
        <div class="dialog-content" @onclick:stopPropagation>
            <h5>Revoke Session</h5>
            <p>
                Are you sure you want to revoke the session on
                <strong>@Session?.Device</strong> from <strong>@Session?.Location</strong>?
            </p>
            <p class="text-muted">This will sign the device out immediately.</p>
            <div class="dialog-actions">
                <button class="btn btn-outline-secondary" @onclick="Cancel">Cancel</button>
                <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
            </div>
        </div>
    </div>
}

@code {
    using sv_fa463c93198b4e7c938f438ce6449c95.Services;

    [Parameter]
    public bool Visible { get; set; }

    [Parameter]
    public ActiveSession? Session { get; set; }

    [Parameter]
    public EventCallback OnConfirm { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

.dialog-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.dialog-content {
    background: white;
    border-radius: 0.5rem;
    padding: 1.5rem;
    max-width: 440px;
    width: 90%;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
    margin-top: 1.25rem;
}

@using sv_fa463c93198b4e7c938f438ce6449c95.Services

<div class="security-section">
    <h3>Security</h3>

    @if (SecuritySettings is null)
    {
        <p class="text-muted">Loading security settings…</p>
        return;
    }

    @* ── Change Password ── *@
    <div class="panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>🔑 Change Password</span>
            <span class="chevron @(_passwordExpanded ? "open" : "")">▶</span>
        </button>

        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="_currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="_confirmPassword" />
                </div>

                @if (_passwordError is not null)
                {
                    <div class="alert alert-danger">@_passwordError</div>
                }
                @if (_passwordSuccess)
                {
                    <div class="alert alert-success">✅ Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating…" : "Update Password")
                </button>
            </div>
        }
    </div>

    @* ── Two-Factor Authentication ── *@
    <div class="panel">
        <div class="panel-header static">
            <div class="tfa-row">
                <div>
                    <span>🛡️ Two-Factor Authentication</span>
                    <span class="badge @(SecuritySettings.TwoFactorEnabled ? "bg-success" : "bg-secondary") ms-2">
                        @(SecuritySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" checked="@SecuritySettings.TwoFactorEnabled" disabled />
                    <span class="slider"></span>
                </label>
            </div>
        </div>
        @if (SecuritySettings.LastPasswordChange.HasValue)
        {
            <div class="panel-body">
                <small class="text-muted">
                    Last password change: @SecuritySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </small>
            </div>
        }
    </div>

    @* ── Active Sessions ── *@
    <h5 class="mt-4">Active Sessions</h5>
    <div class="table-responsive">
        <table class="table table-hover">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in SecuritySettings.Sessions)
                {
                    var isCurrent = session == SecuritySettings.Sessions.FirstOrDefault();
                    <tr>
                        <td>
                            @session.Device
                            @if (isCurrent)
                            {
                                <span class="badge bg-primary ms-1">Current</span>
                            }
                        </td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("MMM dd, yyyy h:mm tt")</td>
                        <td>
                            @if (!isCurrent)
                            {
                                <button class="btn btn-sm btn-outline-danger"
                                        @onclick="() => ShowRevokeDialog(session)">
                                    Revoke
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <RevokeSessionDialog Visible="_showRevokeDialog"
                         Session="_sessionToRevoke"
                         OnConfirm="RevokeConfirmedAsync"
                         OnCancel="() => _showRevokeDialog = false" />
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings? SecuritySettings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _passwordSuccess;
    private bool _changingPassword;

    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "Please fill in all password fields.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }

        _changingPassword = true;

        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void ShowRevokeDialog(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task RevokeConfirmedAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
    }
}

