{"file_text": ".security-section {
    max-width: 700px;
}

.panel {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
    text-align: left;
}

.panel-header.static {
    cursor: default;
}

.chevron {
    font-size: 0.75rem;
    transition: transform 0.2s;
}

.chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem 1.25rem;
    border-top: 1px solid #dee2e6;
}

.tfa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
}

/* Toggle switch (shared style with notifications) */
.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}
