arguments.file_text:
@using sv_fa463c93198b4e7c938f438ce6449c95.Services

<div class="appearance-section">
    <h3>Appearance</h3>

    @if (Settings is null)
    {
        <p class="text-muted">Loading appearance settings…</p>
        return;
    }

    <div class="settings-and-preview">
        <div class="settings-controls">
            @* ── Theme ── *@
            <fieldset class="mb-4">
                <legend class="form-label fw-semibold">Theme</legend>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-option @(_theme == theme ? "selected" : "")">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </fieldset>

            @* ── Font Size ── *@
            <fieldset class="mb-4">
                <legend class="form-label fw-semibold">Font Size</legend>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-option @(_fontSize == size ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </fieldset>

            @* ── Language ── *@
            <div class="mb-4">
                <label class="form-label fw-semibold">Language</label>
                <select class="form-select" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                    <option value="pt">Portuguese</option>
                </select>
            </div>

            @* ── Compact Mode ── *@
            <div class="mb-4">
                <div class="toggle-row">
                    <div>
                        <span class="fw-semibold">Compact Mode</span>
                        <div class="text-muted small">Reduce spacing and element sizes</div>
                    </div>
                    <label class="switch">
                        <input type="checkbox" checked="@_compactMode"
                               @onchange="e => _compactMode = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save")
            </button>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3" role="alert">
                    ✅ Appearance settings saved!
                </div>
            }
        </div>

        @* ── Live Preview ── *@
        <div class="preview-panel @GetPreviewClasses()">
            <div class="preview-label">Preview</div>
            <div class="preview-card">
                <h6>Dashboard</h6>
                <p>Welcome back! Here's your activity summary for this week.</p>
                <div class="preview-stats">
                    <div class="preview-stat">
                        <span class="stat-value">24</span>
                        <span class="stat-label">Tasks</span>
                    </div>
                    <div class="preview-stat">
                        <span class="stat-value">8</span>
                        <span class="stat-label">Messages</span>
                    </div>
                    <div class="preview-stat">
                        <span class="stat-value">3</span>
                        <span class="stat-label">Alerts</span>
                    </div>
                </div>
                <button class="preview-btn">View Details</button>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);

        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section {
    max-width: 800px;
}

.settings-and-preview {
    display: flex;
    gap: 2rem;
    align-items: flex-start;
}

.settings-controls {
    flex: 1;
    min-width: 280px;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
}

.radio-option {
    display: flex;
