    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    cursor: pointer;
    transition: border-color 0.15s, background-color 0.15s;
}

.radio-option:hover {
    background: #f8f9fa;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
}

.radio-option input[type="radio"] {
    accent-color: #0d6efd;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

/* Toggle switch */
.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* ── Live Preview ── */
.preview-panel {
    flex: 1;
    min-width: 260px;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.3s ease;
}

.preview-label {
