.settings-and-preview {
    display: flex;
    gap: 2rem;
    align-items: flex-start;
}

.settings-controls {
    flex: 1;
    min-width: 280px;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    cursor: pointer;
    transition: border-color 0.15s, background-color 0.15s;
}

.radio-option:hover {
    background: #f8f9fa;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
}

