.settings-and-preview {
    display: flex;
    gap: 2rem;
    align-items: flex-start;
}

.settings-controls {
    flex: 1;
    min-width: 280px;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    cursor: pointer;
    transition: border-color 0.15s, background-color 0.15s;
}

.radio-option:hover {
    background: #f8f9fa;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
}

.radio-option input[type="radio"] {
    accent-color: #0d6efd;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

/* Toggle switch */
.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* ── Live Preview ── */
.preview-panel {
    flex: 1;
    min-width: 260px;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.3s ease;
}

.preview-label {
    padding: 0.5rem 1rem;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 1px solid #dee2e6;
    background: #f8f9fa;
    color: #6c757d;
}

.preview-card {
    padding: 1.25rem;
    transition: padding 0.3s, font-size 0.3s;
}

.preview-card h6 {
    margin-bottom: 0.5rem;
}

.preview-card p {
    margin-bottom: 1rem;
    color: #6c757d;
}

.preview-stats {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
}

.preview-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
}

.stat-value {
    font-size: 1.25rem;
    font-weight: 700;
}

.stat-label {
    font-size: 0.75rem;
    color: #6c757d;
}

.preview-btn {
    padding: 0.375rem 1rem;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: white;
    border-radius: 0.375rem;
    cursor: default;
    font-size: 0.875rem;
}

/* Theme variants */
.theme-dark .preview-label {
    background: #343a40;
    color: #adb5bd;
    border-color: #495057;
}

.theme-dark .preview-card {
    background: #212529;
