}

.theme-dark .preview-stat {
    background: #343a40;
}

.theme-dark .stat-label {
    color: #adb5bd;
}

.theme-dark {
    border-color: #495057;
}

.theme-system .preview-label {
    background: linear-gradient(90deg, #f8f9fa 50%, #343a40 50%);
    color: #6c757d;
}

/* Font sizes */
.font-small .preview-card {
    font-size: 0.8rem;
}

.font-small .stat-value {
    font-size: 1rem;
}

.font-medium .preview-card {
    font-size: 0.95rem;
}

.font-large .preview-card {
    font-size: 1.1rem;
}

.font-large .stat-value {
    font-size: 1.5rem;
}

/* Compact mode */
