arguments.file_text:
@page "/settings"
@using sv_fa463c93198b4e7c938f438ce6449c95.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="_profile" OnSave="SaveProfileAsync" />
                break;

            case "Notifications":
                <NotificationsSection Prefs="_notificationPrefs" OnSave="SaveNotificationsAsync" />
                break;

            case "Security":
                <SecuritySection SecuritySettings="_securitySettings"
                                 OnChangePassword="ChangePasswordAsync"
                                 OnRevokeSession="RevokeSessionAsync" />
                break;

            case "Appearance":
                <AppearanceSection Settings="_appearance" OnSave="SaveAppearanceAsync" />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync(_activeSection);
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // Eagerly load data for the active section if not already loaded.
    }

    private async Task LoadSectionDataAsync(string section)
    {
        switch (section)
        {
            case "Profile" when _profile is null:
                _profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications" when _notificationPrefs is null:
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security" when _securitySettings is null:
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance" when _appearance is null:
                _appearance = await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 60px);
    background: #fff;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

